    #include "addcode.S"
#endif

/* FPSP always put at the end of the ROM (for now) due to the size */
#ifdef INSTALL_FPSP
    #include "fpsp-callouts.S"
#endif

/* ################################################################################
| stick some build info on the very end of the ROM */

.section .text.end
    .ascii "\n\n"       /* clear lines off end of ROM if viewed in a text editor */
ROMBuild:
    .ascii "zigzagjoe 68060-Q650 ROM\n"
    .ascii xpandstr(built BUILD_DATE \n)
    .ascii xpandstr(git rev GIT_REV \n)
#ifdef DISABLE_FPU 
    .ascii "FPU Disabled\n"
#endif
#ifdef INSTALL_FPSP
    .ascii "FPSP (FPU) Enabled\n"
#endif
#ifdef ENABLE_SUPERSCALAR 
    .ascii "Superscalar Enabled\n"
#endif
#ifdef ENABLE_BRANCH_CACHE 
    .ascii "Branch Cache Enabled\n"
#endif
#ifdef ENABLE_SERIAL_DEBUG
    .ascii "Serial Debug Enabled\n"
#endif
#ifdef PATCH_FORCE_32BIT
    .ascii "Force 32-bit only\n"
#endif
#ifdef PATCH_BIGSIMMS_HACK
    .ascii "Big SIMMs support hack\n"
#endif
#ifdef PATCH_DRAM_SIMMONLY
    .ascii "Onboard RAM disabled\n"
#endif
#ifdef FORCE_DRAM_TIMINGS
    .ascii "Forced DRAM timings\n"
#endif

    .byte 0
.section .text
